import{_ as i,o as e,c as a,aO as o}from"./chunks/framework.BFrk9dwu.js";const l="/recipes/braised-pork.jpg",r="/recipes/braised-pork/top-2.jpg",d="/recipes/braised-pork/top-3.jpg",s="/recipes/braised-pork/step-1-a.jpg",p="/recipes/braised-pork/step-2-a.jpg",n="/recipes/braised-pork/step-3-a.jpg",g="/recipes/braised-pork/step-4-a.jpg",c="/recipes/braised-pork/step-5-a.jpg",h="/recipes/braised-pork/step-6-a.jpg",x=JSON.parse('{"title":"红烧肉","description":"煸油、炒糖色、小火慢炖再收汁的红烧肉做法，含发苦、油厚、肉柴的排查","frontmatter":{"date":"2026-11-19T10:56:55.000Z","title":"红烧肉","description":"煸油、炒糖色、小火慢炖再收汁的红烧肉做法，含发苦、油厚、肉柴的排查","permalink":"/pages/d8e821","categories":["life","recipes"]},"headers":[],"relativePath":"life/recipes/braised-pork.md","filePath":"life/recipes/braised-pork.md"}'),m={name:"life/recipes/braised-pork.md"};function _(b,t,u,f,k,y){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="红烧肉" tabindex="-1">红烧肉 <a class="header-anchor" href="#红烧肉" aria-label="Permalink to &quot;红烧肉&quot;">​</a></h1><div class="recipe-gallery"><img src="'+l+'" alt="红烧肉成品：白瓷碗里枣红油亮的方块，撒了白芝麻与葱花"><img src="'+r+'" alt="俯拍特写：红烧肉肥瘦分层、酱汁挂在表面"><img src="'+d+'" alt="小碗里的红烧肉配白米饭，筷子平搁在碗边"><img loading="lazy" src="'+s+'" alt="案板上整块带皮五花肉，旁边菜刀与切下的方块"></div><p>红烧肉看着难，其实就四件事：肉挑对、油煸掉、糖色别炒过、火要小。糖色和收汁这两步最看手上功夫，颜色对了才算成。</p><h2 id="用料" tabindex="-1">用料 <a class="header-anchor" href="#用料" aria-label="Permalink to &quot;用料&quot;">​</a></h2><p><strong>主料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>带皮五花肉</td><td>切 3cm 方块，挑三层肥瘦分明的，炖完还会缩一圈</td></tr><tr><td>生姜</td><td>焯水、炒香料各几片</td></tr><tr><td>小葱</td><td>出锅撒葱花</td></tr></tbody></table><p><strong>配料与调料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>冰糖</td><td>炒糖色用，没有就用等量白糖</td></tr><tr><td>食用油</td><td>炒糖色用，别多，肉本身会出油</td></tr><tr><td>八角</td><td>两个就够，多了发苦</td></tr><tr><td>桂皮</td><td>一小段</td></tr><tr><td>干辣椒</td><td>不吃辣可以不放</td></tr><tr><td>料酒</td><td>焯水、炒制各一次</td></tr><tr><td>生抽</td><td>调味主力</td></tr><tr><td>老抽</td><td>只管上色，多了发黑</td></tr><tr><td>热水</td><td>必须热水，冷水一激肉就紧</td></tr><tr><td>盐</td><td>收汁前尝过再决定补不补</td></tr></tbody></table><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><ol><li><p><strong>切块。</strong> 五花肉洗净擦干，切 3cm 见方的块。块别切小，炖完会缩一圈，太小的块炖出来只剩一点。</p><figure class="recipe-shots"><img loading="lazy" src="'+s+'" alt="案板上整块带皮五花肉，旁边菜刀与切下的方块"></figure></li><li><p><strong>冷水焯水。</strong> 肉块冷水下锅，加姜、料酒，水开后撇净浮沫，煮 3 分钟捞出，用温水冲净、控干水分。控干很关键，带水下锅会溅油，也煸不出油。</p><figure class="recipe-shots"><img loading="lazy" src="'+p+'" alt="五花肉块冷水下锅，水面浮起灰白浮沫"></figure></li><li><p><strong>煸出油。</strong> 锅不放油，肉块皮朝下摊平，中小火煸到肥肉出油、肉皮泛黄起小泡。煸出的猪油盛出大半，锅里留一层润锅就够。这步决定成菜会不会腻，油不煸出去，最后就是一碗油泡肉。</p><figure class="recipe-shots"><img loading="lazy" src="'+n+'" alt="肉块皮朝下在锅里煸，锅底已经出了一层猪油"></figure></li><li><p><strong>炒糖色。</strong> 转最小火，下油和冰糖，慢慢炒到化开、变成枣红色起细密小泡，立刻把肉块倒进去翻匀。看颜色别看时间，枣红一到就下肉，多炒十秒就是苦的。</p><figure class="recipe-shots"><img loading="lazy" src="'+g+'" alt="冰糖在油里化成枣红色、起小泡，旁边备着肉块"></figure></li><li><p><strong>下香料和酱油。</strong> 加姜片、八角、桂皮、干辣椒炒香，沿锅边淋料酒，再加生抽、老抽翻匀上色。</p><figure class="recipe-shots"><img loading="lazy" src="'+c+'" alt="姜片、八角、桂皮、干辣椒下锅炒香"></figure></li><li><p><strong>热水慢炖。</strong> 倒热水没过肉块，大火烧开转最小火，盖盖炖一小时。中途别加冷水，要加也加热水。</p><figure class="recipe-shots"><img loading="lazy" src="'+h+'" alt="热水没过肉块，汤色深红、浮着姜片八角"></figure></li><li><p><strong>大火收汁。</strong> 开盖看肉皮发亮、筷子能轻松插透，就转大火收汁，让汤汁翻滚收浓。</p></li><li><p><strong>出锅。</strong> 收到酱汁能挂住勺背、裹在每块肉上就关火，撒葱花和白芝麻。别收到发干，凉了还会更稠。</p><figure class="recipe-shots"><img src="'+r+'" alt="俯拍特写：红烧肉肥瘦分层、酱汁挂在表面"></figure></li></ol><h2 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h2><ul><li><strong>挑三层分明的五花</strong>：肥瘦层次清楚才不腻，别用纯肥的。</li><li><strong>先煸油，再炒糖色</strong>：油煸出去肉才不腻，也不容易崩油。</li><li><strong>糖色看颜色不看时间</strong>：枣红起小泡就下肉，再等就发苦。</li><li><strong>全程热水、小火炖</strong>：冷水一激肉就紧，火大了汤汁浑浊、肉散。</li><li><strong>收汁到挂勺就停</strong>：锅里看着稀一点正常，凉了会变稠。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">偷懒版</p><p>不会炒糖色就跳过第 4 步，直接用老抽上色，颜色浅一点但不会翻车。也可以用高压锅压 20 分钟，再倒回锅里收汁。</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">常见翻车</p><p></p><ul><li><strong>发苦</strong>：糖色炒过头了，或者八角放多了。</li><li><strong>发黑不发红</strong>：老抽倒多了，糖色又没炒到位。</li><li><strong>太油腻</strong>：第 3 步没煸油，或者油没盛出去。</li><li><strong>肉柴不糯</strong>：中途加了冷水，或者炖的时间不够。</li><li><strong>汁发涩不亮</strong>：收汁时火太大，汁收干烧焦了。</li></ul></div><p><a href="/life/recipes/">← 回菜谱总览</a></p>',15)])])}const P=i(m,[["render",_]]);export{x as __pageData,P as default};
